def discounted_total(total: float, *, member: bool = False) -> float:
    """Return the order total after an optional member discount."""
    if total < 0:
        raise ValueError('total cannot be negative')

    rate = 0.10 if member else 0.0
    return total * (1 - rate)

print(discounted_total(80.0, member=True))

