def remaining_budget(limit: float, spent: float, *, include_pending: bool = False) -> float:
    if limit < 0 or spent < 0:
        raise ValueError('limit and spent must be non-negative')

    pending_charge = 5.0 if include_pending else 0.0
    effective_spent = spent + pending_charge
    return limit - effective_spent

lab.testCode:
assert remaining_budget(20, 7) == 13
assert remaining_budget(20, 7, include_pending=True) == 8
try:
    remaining_budget(-1, 0)
except ValueError:
    print('PASS: budget calculation and invalid input')
else:
    raise AssertionError('negative limit must fail')
